def op_random(sol, k, ctx):
    bs = sol_boxes(sol)
    if len(bs) <= k:
        return sol, bs
    pick = RNG.sample(bs, k)
    return remove_boxes(sol, pick), pick


def op_shaw(sol, k, ctx):
    """Shaw 相关移除：以某箱为种子，移除与其“服务区相近且质量相近”的货箱。"""
    bs = sol_boxes(sol)
    if not bs:
        return sol, []
    seed = RNG.choice(bs)
    bm, sid_of = ctx["bm"], ctx["box_sid"]
    area_xy = ctx["area_xy"]

    def rel(b):
        d = float(np.hypot(*(area_xy[sid_of[b]] - area_xy[sid_of[seed]])))
        return d + 500.0 * abs(bm[b] - bm[seed])

    ranked = sorted(bs, key=rel)
    pick = ranked[:min(k, len(bs))]
    return remove_boxes(sol, pick), pick


def op_worst(sol, k, ctx):
    """最差移除：优先移除“单位质量运输代价高、位置偏远”的货箱。"""
    bs = sol_boxes(sol)
    if not bs:
        return sol, []
    sc, bm = ctx["sc"], ctx["bm"]
    sid_of = ctx["box_sid"]

    def cost(b):
        s_out = sc.seg("O01", sid_of[b])
        return (s_out["d"] * bm[b] / 1000.0) * (1.0 + s_out["hup"] / 1000.0)

    ranked = sorted(bs, key=cost, reverse=True)
    pick = ranked[:min(k, len(bs))]
    return remove_boxes(sol, pick), pick


def op_route(sol, k, ctx):
    """整架次移除：随机移除一个完整架次。"""
    if len(sol) <= 1:
        return op_random(sol, k, ctx)
    j = RNG.randrange(len(sol))
    pick = [b for st in sol[j]["stops"] for b in st["boxes"]]
    return remove_boxes(sol, pick), pick


def op_area(sol, k, ctx):
    """按服务区移除：随机选一个服务区，移除其全部货箱。"""
    sid_of = ctx["box_sid"]
    bs = sol_boxes(sol)
    sids = sorted({sid_of[b] for b in bs})
    if not sids:
        return sol, []
    sid = RNG.choice(sids)
    pick = [b for b in bs if sid_of[b] == sid]
    return remove_boxes(sol, pick), pick

def plan_relays(sc, need_points, max_per_station_span=3600.0):
    """贪心集合覆盖 + 时间聚类，把需要中继的检查点组织成若干中继架次。

    need_points : [(时刻, 检查点键, 候选站点索引列表)]
    返回 (deployments, uncovered_count)
    """
    rt = sc.rtypes["R"]
    remaining = list(need_points)
    deployments = []
    while remaining:
        # 统计每个站点能覆盖的剩余需求数
        cnt = {}
        for _, _, sts in remaining:
            for s in sts:
                cnt[s] = cnt.get(s, 0) + 1
        if not cnt:
            break
        best = max(cnt, key=lambda k: (cnt[k], -k))
        mine = [r for r in remaining if best in r[2]]
        remaining = [r for r in remaining if best not in r[2]]
        # 需要中继但该站点也覆盖不到的点（同批中无候选的）另行处理
        times = sorted(t for t, _, _ in mine)
        # 按时间聚类：间隔超过阈值则拆分为多个架次
        groups, cur = [], [times[0]]
        for x in times[1:]:
            if x - cur[-1] > max_per_station_span:
                groups.append(cur)
                cur = [x]
            else:
                cur.append(x)
        groups.append(cur)
        st = sc_station(sc, best)
        for gp in groups:
            deployments.append(dict(station=best, t0=gp[0], t1=gp[-1],
                                    n_points=len(gp)))
    return deployments, len(remaining)

