def eq_range_s(g, q):
    """等效航程 L_g(q)，标量版。"""
    L0, LF, Q = g["L0"], g["LF"], g["Q_max"]
    r = (0.0 if q < 0.0 else (Q if q > Q else q)) / Q
    return L0 - (L0 - LF) * r ** 1.5


def seg_E_s(g, q, seg):
    """航段能耗 (kWh)，标量版：水平巡航 + 爬升附加。"""
    return (seg["d"] * g["E_use"] / eq_range_s(g, q)
            + (g["m_empty"] + q) * G_ACC * seg["hup"] / (g["eta_up"] * J_PER_KWH))


def seg_T_s(g, seg):
    """航段飞行时间 (s)，标量版。"""
    return seg["hup"] / g["v_up"] + seg["d"] / g["v_cruise"] + seg["hdn"] / g["v_down"]

