def blocked_windows(s):
    kk=s['k']; p=machines[kk]; windows=[]; t=s['start']; prev='O01'
    def chk(t,h,lo,la): 
        return los_blocked(G01_lon,G01_lat,G01_h, lo,la,h)
    for b in s['seq']:
        lon1,lat1=node_lonlat(prev); lon2,lat2=node_lonlat(b)
        d=Dm(prev,b); hc=max(ground[prev],ground[b])+50.0; h1=op_h[prev]; h2=op_h[b]
        T=(hc-h1)/p['vc']+d/p['v']+(hc-h2)/p['vd']
        for frac in np.linspace(0,1,40):
            lo=lon1+(lon2-lon1)*frac; la=lat1+(lat2-lat1)*frac
            if frac<0.3: h=h1+(hc-h1)*(frac/0.3)
            elif frac>0.7: h=hc-(hc-h2)*((frac-0.7)/0.3)
            else: h=hc
            if chk(t+frac*T,h,lo,la): windows.append(t+frac*T)
        t+=T; prev=b
    # 归并
    if not windows: return None
    windows=sorted(windows); merged=[[windows[0],windows[0]]]
    for w in windows[1:]:
        if w-merged[-1][1]<=60: merged[-1][1]=w
        else: merged.append([w,w])
    return merged

